import 'dart:async';

import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';

/// Every sound the app can play. File: `assets/sounds/<name>.wav`
/// (generated by `tools/make_sounds.py`).
enum Sfx {
  tap('tap'),
  chip('chip'),
  error('error'),
  coin('coin'),
  spin('spin'),
  reelStop('reel_stop'),
  win('win'),
  bigWin('big_win'),
  lose('lose'),
  card('card'),
  cardFlip('card_flip'),
  blackjack('blackjack'),
  diceRoll('dice_roll'),
  rouletteSpin('roulette_spin'),
  ballDrop('ball_drop'),
  crashStart('crash_start'),
  crashTick('crash_tick'),
  cashOut('cash_out'),
  bust('bust');

  const Sfx(this.file);
  final String file;
}

/// Game sounds and the per-game music loops. Same idea as [AppHaptics]: a static switch
/// that the profile settings turn on and off, so a game just calls
/// `AppSound.play(Sfx.win)` and never checks a setting.
///
/// Sounds never throw. If audio is not available (a test, a simulator without
/// output) the call is silently ignored.
class AppSound {
  AppSound._();

  static bool enabled = true;
  static bool musicEnabled = true;

  static const int _voices = 6;
  static final List<AudioPlayer> _pool = [];
  static int _next = 0;
  static AudioPlayer? _music;
  static bool _ready = false;

  /// Sounds mixed in the game, quieter than a full-volume effect.
  static const double _sfxVolume = .9;
  static const double _musicVolume = .22;

  /// Call once at start-up. Lets the app's sounds mix with other apps' audio
  /// (a podcast keeps playing) instead of stopping them.
  static Future<void> init() async {
    if (_ready) return;
    _ready = true;
    try {
      await AudioPlayer.global.setAudioContext(AudioContextConfig(focus: AudioContextConfigFocus.mixWithOthers).build());
    } catch (e) {
      debugPrint('AppSound.init: $e');
    }
  }

  static void play(Sfx sfx, {double volume = 1}) {
    if (!enabled) return;
    unawaited(_play(sfx, volume));
  }

  static Future<void> _play(Sfx sfx, double volume) async {
    try {
      if (_pool.isEmpty) {
        for (var i = 0; i < _voices; i++) {
          final p = AudioPlayer();
          await p.setReleaseMode(ReleaseMode.stop);
          _pool.add(p);
        }
      }
      final p = _pool[_next];
      _next = (_next + 1) % _voices;
      await p.stop();
      await p.play(AssetSource('sounds/${sfx.file}.wav'), volume: (volume * _sfxVolume).clamp(0.0, 1.0));
    } catch (e) {
      debugPrint('AppSound.play(${sfx.file}): $e');
    }
  }

  /// Plays the loop for one game (`slots`, `roulette`, `blackjack`, `dice`, `crash`).
  /// There is no lobby or app-wide music, so call [stopMusic] when the game closes.
  /// Safe to call again for the same game.
  static void playMusic(String game) {
    _track = game.isEmpty ? null : game;
    _queue(_sync);
  }

  static void stopMusic() {
    _track = null;
    _queue(_sync);
  }

  /// Apply the player's two switches. Starts or stops the current game's loop to match.
  static void apply({required bool sound, required bool music}) {
    enabled = sound;
    musicEnabled = music;
    _queue(_sync);
  }

  /// Back to the defaults (sound on). Called when someone signs out, so the next
  /// player never inherits the previous player's switches.
  static void reset() {
    enabled = true;
    musicEnabled = true;
    stopMusic();
  }

  /// Games that share another game's loop.
  static const Map<String, String> _musicFile = {'plinko': 'dice'};

  static String? _track;
  static String? _playing;
  static Future<void> _chain = Future.value();

  // Every start/stop runs one after the other. Without this, "stop" could arrive
  // while the player was still being created and the music started anyway.
  static void _queue(Future<void> Function() job) {
    _chain = _chain.then((_) => job()).catchError((Object e) {
      debugPrint('AppSound.music: $e');
    });
  }

  static Future<void> _sync() async {
    final want = musicEnabled ? _track : null;
    if (want == _playing) return;
    if (want == null) {
      _playing = null;
      await _music?.stop();
      return;
    }
    final m = _music ??= AudioPlayer();
    await m.setReleaseMode(ReleaseMode.loop);
    await m.setVolume(_musicVolume);
    await m.play(AssetSource('sounds/music_${_musicFile[want] ?? want}.wav'), volume: _musicVolume);
    _playing = want;
  }
}
